// 🟢 LIVE ENGINE: Video අයින් කර Simple/Capital වෙනසත් හදන Filter Engine එක
useEffect(() => {
  if (!targetGrade) return;
  axios.get('http://localhost:8082/api/learning-materials')
    .then(res => {
      const allMaterials = Array.isArray(res.data) ? res.data : [];
      
      const filteredLessonsOnly = allMaterials.filter(m => {
        const isGradeMatch = String(m.grade).toLowerCase() === String(targetGrade).toLowerCase();
        const isNotVideo = (m.material_type || '').toLowerCase() !== 'video' && 
                           !(m.title || '').toLowerCase().includes('video');
        return isGradeMatch && isNotVideo;
      });

      // 🟢 SMART CASE-INSENSITIVE DEDUPLICATION (lesson 02 සහ Lesson 02 එකට එකතු කරයි)
      const uniqueMap = new Map();
      filteredLessonsOnly.forEach(m => {
        if (m.title) {
          const rawTitle = m.title.trim();
          // මුල් අකුර Capital කරයි (lesson 02 -> Lesson 02)
          const formattedTitle = rawTitle.charAt(0).toUpperCase() + rawTitle.slice(1);
          const lowerKey = formattedTitle.toLowerCase();
          
          if (!uniqueMap.has(lowerKey)) {
            uniqueMap.set(lowerKey, formattedTitle);
          }
        }
      });

      const cleanLessonList = Array.from(uniqueMap.values());

      setPublishedLessons(cleanLessonList);
      
      if (cleanLessonList.length > 0) {
        setTargetLesson(cleanLessonList[0]);
      } else {
        setTargetLesson('General Practice');
      }
    })
    .catch(err => console.error("Error linking to Content Manager rows:", err));
}, [targetGrade, bankQuestions]);
